"Bayıldın ve gözlerini klinikte açtın. Hemşire robot sana yıldızlı yara bandı yapıştırdı. Fatura: {0}.":"You passed out and woke up in the clinic. A nurse robot stuck a starry bandage on you. Bill: {0}.",
