"Güneş Fırtınası":"Solar Storm",
"Güneş bugün biraz huysuz. Hurda bölgelerine çıkış yasak. İstasyonda iş bul ya da kek ye.":"The sun's a bit cranky today. Scrap zones are off-limits. Find work on the station or eat some cake.",
"Radyasyon fırtınası. Dışarı çıkan geri dönmüyor. Hurda avı bugün kapalı.":"Radiation storm. Whoever goes out doesn't come back. Scrap hunting is closed today.",
"Fiyat Patlaması":"Price Spike",
"{0} fiyatları uçtu! Zara heyecandan gözlüğünü düşürdü.":"{0} prices are through the roof! Zara dropped her glasses in excitement.",
"{0} fiyatı yükseldi. Bir şirket stok yapıyor. Fırsat bu.":"{0} prices went up. Some corporation is stockpiling. Here's your chance.",
"Piyasa Çöküşü":"Market Crash",
"{0} fiyatları yerlerde. Biri pazara bir dağ dolusu boşaltmış.":"{0} prices hit rock bottom. Someone dumped a mountain of it on the market.",
"{0} değersizleşti. Elinde varsa bekle ya da zararına sat.":"{0} is worth next to nothing. If you've got some, hold — or sell at a loss.",
"Korsan Baskını":"Pirate Raid",
"Korsanlar gece gemine girdi ve... sadece sandviçini çaldılar. Not bırakmışlar: \"Mayonez az.\" Tokluk -20.":"Pirates boarded your ship overnight and... only stole your sandwich. They left a note: \"Needs more mayo.\" Fullness -20.",
"Korsanlar gece gemine girdi ve erzağını aldı. Tokluk -20.":"Pirates boarded your ship overnight and took your provisions. Fullness -20.",
"Kargodan {0} da gitti.":"And {0} vanished from the cargo too.",
"Korsanlar rıhtımı bastı, {0} götürdü ve giderken el salladı.{1}":"Pirates raided the dock, made off with {0} and waved goodbye.{1}",
"Korsanlar rıhtımı bastı. {0} kaybettin.{1}":"Pirates raided the dock. You lost {0}.{1}",
"Uzay Gribi":"Space Flu",
"Uzay gribine yakalandın. Hapşırdıkça hafifçe süzülüyorsun. Sağlık -15.":"You caught space flu. Every sneeze makes you float a little. Health -15.",
"Ateşin var. İstasyonun havası yine kirli. Sağlık -15.":"You've got a fever. The station air is filthy again. Health -15.",
"Kayıp Cüzdan":"Lost Wallet",
"Kantinin koltuğunun altında {0} buldun. Ve bir de kanepe yaratığı. O kalsın.":"You found {0} under the cantina couch. Also a couch creature. Leave that one.",
"Ölü bir hurdacının dolabı boşaltılıyordu. Kimse görmeden {0} aldın.":"They were clearing out a dead scrapper's locker. You pocketed {0} before anyone noticed.",
"Hurda Yağmuru":"Scrap Shower",
"Bir kargo gemisi gece takla atmış! Bugün hurdalar %30 daha değerli.":"A cargo ship did a somersault overnight! Scrap is worth 30% more today.",
"Bir yolcu gemisi parçalanmış. Bugün hurdalar %30 daha değerli. Kimse sormuyor neden.":"A passenger ship broke apart. Scrap is worth 30% more today. Nobody's asking why.",
"İstasyon Festivali":"Station Festival",
"Yıldönümü festivali! Konfeti var, müzik var, robot dans yarışması var. Moral +15.":"Anniversary festival! Confetti, music, a robot dance contest. Morale +15.",
"Yönetim \"Dayanışma Günü\" ilan etti. Bedava çorba var. Moral +15.":"Management declared \"Solidarity Day.\" Free soup. Morale +15.",
"Rex Önden Gitti":"Rex Got There First",
"Rex Asteroit Kuşağı'nı sabah 5'te süpürmüş. Bugün orada az şey kaldı.":"Rex swept the Asteroid Belt at 5 a.m. Slim pickings there today.",
"Rex ve ekibi Asteroit Kuşağı'nı boşaltmış. Bugün orada az şey var.":"Rex and his crew stripped the Asteroid Belt. Not much left there today.",
"Yakıt Zammı":"Fuel Hike",
"Yakıt bugün pahalı. Bir yakıt bürokratı hapşırmış, fiyat kaçmış.":"Fuel is pricey today. A fuel bureaucrat sneezed and the price bolted.",
"Yakıt kartelleri bugün fiyatı ikiye katladı.":"The fuel cartels doubled the price today.",
"Lisans Denetimi":"License Inspection",
"Denetçi geminin selfie çekmeye uygun olmadığını söyledi. Ceza: {0}.":"The inspector says your ship isn't selfie-ready. Fine: {0}.",
"Denetçi ruhsatında bir \"eksik\" buldu. Rüşvet ya da ceza: {0}.":"The inspector found something \"missing\" in your permit. Bribe or fine: {0}.",
"Banka kredisinin süresi {0} gün sonra doluyor. Kalan borç {1}; dolarsa banka {2}'ya el koyar.":"The bank loan is due in {0} days. Remaining debt: {1}. If it lapses, the bank seizes the {2}.",
"Krell'in süresinin bitmesine {0} gün kaldı.":"{0} days left on Krell's deadline.",
