"Atlarsan tokluğun 15 daha düşer.":"Skip it and your fullness drops another 15.",
"Isıtma":"Heating",
"Kapatırsan moral -6, sağlık -3; arkadaşların hastalanabilir.":"Turn it off: morale -6, health -3; your companions may get sick.",
"Pıtırcık: şarj ve yağ":"Pıtırcık: charge and oil",
"(şarj yuvası)":"(charging dock)",
"(premium yağ)":"(premium oil)",
"Şarj edilmezse yarın kapalı kalır, bağ -6.":"If not charged, it stays down tomorrow, bond -6.",
"{0}: yemek":"{0}: food",
"Aç kalırsa bağ -10. İki gece üst üste aç kalan hastalanır.":"Going hungry: bond -10. Two hungry nights in a row means getting sick.",
"İlaç: {0}":"Medicine: {0}",
"İlaçsız {0} gece daha geçerse seni terk eder.":"{0} more nights without medicine and they'll leave you.",
"Ödemezsen Ela okuldan uzaklaştırılır: bağ -12, moral -4.":"Don't pay and Ela gets suspended from school: bond -12, morale -4.",
"{0} (ödenemedi, ceza {1})":"{0} (unpaid, penalty {1})",
"(ödenemedi)":"(unpaid)",
"Borca eklenen faiz (%{0})":"Interest added to debt ({0}%)",
"Akşam yemeğini atladın. Mideni \"tasarruf modu\"na aldın.":"You skipped dinner. Your stomach is now in \"power-saving mode.\"",
"Aç yattın. Tasarruf, karnı doyurmuyor.":"You went to bed hungry. Saving money doesn't fill a belly.",
"Isıtmayı kapattın. Pencerede buz çiçekleri var, çok estetik, çok soğuk.":"You turned the heating off. Frost flowers on the window — very aesthetic, very cold.",
"Isıtma kapalıydı. Gece boyunca nefesin buhar oldu.":"The heating was off. Your breath steamed all night.",
"{0} soğuktan hastalandı.":"{0} caught a cold.",
"Pıtırcık'ın şarjı bitti. Sabah ekranında sadece \"zZz\" yazıyor.":"Pıtırcık ran out of charge. Its morning screen just says \"zZz\".",
"Pıtırcık şarjsız kaldı ve kapandı.":"Pıtırcık ran out of charge and shut down.",
"{0} ikinci gece de aç yattı.":"{0} went to bed hungry for the second night.",
"{0} aç yattı. Midesinin sesini duvardan duyabiliyorsun.":"{0} went to bed hungry. You can hear their stomach through the wall.",
"{0} aç yattı. Bir şey demedi.":"{0} went to bed hungry. Didn't say a word.",
"{0} açlıktan hastalandı.":"{0} got sick from hunger.",
"{0} ilacı aldı, iyileşiyor.":"{0} took the medicine and is getting better.",
"Ela teyzesinin yanına gönderildi. Giderken sana bir resim bıraktı: sen, kocaman bir kanca ve \"iyileşince dönerim\" yazısı.":"Ela was sent to her aunt's. She left you a drawing: you, a giant claw, and \"I'll be back when you're better.\"",
"Sosyal hizmetler Ela'yı aldı. Kapı kapandığında ev hiç olmadığı kadar sessizdi.":"Social services took Ela. When the door shut, the house was quieter than it had ever been.",
"Tolga \"ben bir hastane gemisine katılıyorum, hem tedavi hem iş\" dedi ve gitti.":"Tolga said \"I'm joining a hospital ship — treatment and a job\" and left.",
"Tolga hastalığını taşıyamadı, bir hastane gemisine bindi. Geri döneceğini sanmıyorsun.":"Tolga couldn't carry his illness any longer and boarded a hospital ship. You don't think he's coming back.",
"Pıtırcık tamir edilemedi. Hurdacılar onu parça parça aldı.":"Pıtırcık couldn't be repaired. The scrappers took it apart piece by piece.",
"Ela okul ücreti ödenmediği için bir hafta evde. \"Tatil!\" diyor. Sevinmiyor.":"Ela's home for a week because the school fees weren't paid. \"Holiday!\" she says. She isn't happy.",
"Ela'nın okul kaydı donduruldu. Sessizce kitaplarını topladı.":"Ela's school enrollment was frozen. She quietly packed up her books.",
"Ela bütün akşam odasından çıkmadı. Kapıya \"GİRMEK YASAK (SEN)\" yazmış.":"Ela didn't leave her room all evening. Her door says \"NO ENTRY (YOU)\".",
"Ela akşam yemeğine gelmedi. Kapısının ardından ağladığını duydun.":"Ela didn't come to dinner. You heard her crying behind the door.",
"Pıtırcık gece mutfak robotuyla güreşmiş. Kazanan Pıtırcık, kaybeden bütçe: {0}.":"Pıtırcık wrestled the kitchen robot overnight. Pıtırcık won; the budget lost: {0}.",
"Pıtırcık bir kabloyu kemirmiş, sigorta yandı. Tamir: {0}.":"Pıtırcık chewed a cable and blew a fuse. Repair: {0}.",
"Gecikme sayın: {0}/{1}. {2}. gecikmede oyun biter. Gecikmiş borcu Kaptan > Finans'tan ödeyebilirsin.":"Late payments: {0}/{1}. Late payment #{2} ends the game. You can pay overdue debt from Captain > Finance.",
"Midenin guruldaması komşuları uyandırdı. Sağlık -10.":"Your growling stomach woke the neighbours. Health -10.",
"Açlık vücudunu kemiriyor. Sağlık -10.":"Hunger is gnawing at your body. Health -10.",
"Açlık ve yorgunluk":"Hunger and fatigue",
"Banka kredisi kapandı! Temsilci sana bir kalem hediye etti. Kalem yazmıyor.":"Bank loan paid off! The rep gave you a pen as a gift. The pen doesn't write.",
"Banka kredisi kapandı. Gemi artık tamamen senin.":"Bank loan paid off. The ship is now entirely yours.",
