"Kristal cenneti. Sümüksüler kristalleri sırtında taşır.":"Crystal heaven. Slimes carry crystals on their backs.",
"Korsan Sektörü":"Pirate Sector",
"Çok zengin, çok tehlikeli. Tanklar her yerde.":"Very rich, very dangerous. Tanks everywhere.",
"Kayıp Yıldız":"Lost Star",
"Halcyon gemisinin enkazı. Efsane gerçekmiş.":"The wreck of the Halcyon. The legend was true.",
"Paslı Astronot Kaskı":"Rusty Astronaut Helmet",
"Eski Dünya Plakası":"Old Earth License Plate",
"Donmuş Çay Bardağı":"Frozen Tea Glass",
"Kaptan Köşkü Zili":"Captain's Bridge Bell",
"Kırık Robot Kalbi":"Broken Robot Heart",
"İlk Hiper Sürücü Vidası":"First Hyperdrive Screw",
"Fırtına İncisi":"Storm Pearl",
"Gaz Balinası Dişi":"Gas Whale Tooth",
