"Fırlatıcı Kanca":"Launcher Claw",
"Hurda avı: kanca daha hızlı fırlar. Her seviye satışta hurda değerine +%2,5.":"Scrap hunt: the claw fires faster. Each level adds +2.5% to scrap value when selling.",
"Vinç Motoru":"Winch Motor",
"Hurda avı: ağır yükler daha hızlı sarılır. Her seviye satışta hurda değerine +%2,5.":"Scrap hunt: heavy loads reel in faster. Each level adds +2.5% to scrap value when selling.",
"Manyetik Pençe":"Magnetic Grip",
"Hurda avı: yakalama alanı genişler. Her seviye satışta hurda değerine +%2,5.":"Scrap hunt: wider grab area. Each level adds +2.5% to scrap value when selling.",
"Tarayıcı Radar":"Scanner Radar",
"Hurda avı: kara kutuların ve taklitçilerin içi görünür. Satışta hurda değerine +%2,5.":"Scrap hunt: see inside black boxes and mimics. Adds +2.5% to scrap value when selling.",
"İtici Motorlar":"Thrusters",
"Teslimat: itki %15 güçlü, yakıt %10 az harcanır (seviye başına).":"Delivery: 15% more thrust, 10% less fuel used (per level).",
"Jiroskop":"Gyroscope",
"Teslimat: iniş hızı ve açı toleransı artar.":"Delivery: more tolerance for landing speed and angle.",
"Gövde Zırhı":"Hull Armor",
"Patlama ve sert inişlerde %20 daha az hasar (seviye başına).":"20% less damage from explosions and hard landings (per level).",
"Yakıt Tankı":"Fuel Tank",
"Uzak bölgelere ve uzun teslimatlara yeter.":"Enough for far zones and long deliveries.",
"Kargo Bölmesi":"Cargo Bay",
"Ambar büyür, bir dalışta daha çok taşırsın.":"Bigger hold — carry more per dive.",
"Takım Çantası":"Toolkit",
"Tamir: seviye başına +1 ipucu ve +8 saniye.":"Repair: +1 hint and +8 seconds per level.",
"Sadece hurda avını etkiler":"Affects scrap hunts only",
