"Herkes için aynı alan":"Same field for everyone",
"45 saniye, herkes için aynı enkaz düzeni. Saat, enerji ve yakıt harcamaz; oyundaki ekonomini etkilemez. Skorunu paylaş, arkadaşların seni geçmeye çalışsın.":"45 seconds, the same wreck layout for everyone. Costs no time, energy or fuel; doesn't touch your in-game economy. Share your score and let your friends try to beat you.",
"Arkadaşından gelen kod":"Code from a friend",
"En iyi skorun: {9}":"Your best score: {9}",
"Kod okunamadı. Örnek: MO-2K9F-340":"Couldn't read the code. Example: MO-2K9F-340",
"Anı karesi":"Snapshot",
"Kargo Pilotu Lisansı":"Cargo Pilot License",
"İş Merkezi'nde kargo teslimatı ilanları açılır.":"Unlocks cargo delivery listings at the Job Center.",
"Ders notu: İnişte hızı pistin hemen üstünde kes; yan rüzgârda burnu rüzgâra çevir.":"Lesson note: On landing, kill your speed right above the pad; in a crosswind, point the nose into the wind.",
"Ayrıştırma Sertifikası":"Sorting Certificate",
"Ayrıştırma tesisinde vardiya alabilirsin.":"Lets you take shifts at the sorting facility.",
"Devre Teknisyeni Belgesi":"Circuit Technician Certificate",
"Tamir işleri açılır. Riski az, kazancı istikrarlı.":"Unlocks repair jobs. Low risk, steady pay.",
"Ders notu: Devreyi kaynaktan değil, çıkıştan geriye doğru düşün; dönmeyen parçalar yolu belirler.":"Lesson note: Think through the circuit from the output back, not from the source; the pieces that don't rotate set the path.",
"Ticaret Ruhsatı":"Trade Permit",
"Sipariş ilanları açılır: kargodaki eşyaları pazardan çok daha iyi fiyata teslim edersin.":"Unlocks order listings: deliver goods from your cargo for far better prices than the market.",
"Ders notu: Aynı türden çok satarsan pazar doyar ve fiyat düşer. Siparişler bu sorunu yaşamaz.":"Lesson note: Sell too much of one kind and the market gets saturated and prices drop. Orders don't have that problem.",
"Derin Tarama Sertifikası":"Deep Scan Certificate",
"Derin tarama":"Deep scan",
"Hurda avında kristal, uydu, sümüksü ve kayıp eserler görünür; Gaz Devi Halkası açılır.":"Crystals, satellites, slimes and lost relics show up in scrap hunts; the Gas Giant Ring opens.",
"Ders notu: Kristaller ağırdır ama değerlidir. Vinç geliştirmesi olmadan sabır gerekir.":"Lesson note: Crystals are heavy but valuable. Without a winch upgrade, you'll need patience.",
"Ders notu: Kayıp eserler albüm setlerini tamamlar; her set bir dekor, para ve unvan verir.":"Lesson note: Lost relics complete album sets; each set gives a decoration, cash and a title.",
"Tehlikeli Bölge Lisansı":"Danger Zone License",
"Tehlikeli bölge":"Danger zone",
"Korsan Sektörü ve Kayıp Yıldız yolu açılır. En zengin, en riskli sular.":"Opens the Pirate Sector and the road to the Lost Star. The richest, riskiest waters.",
"Ders notu: Korsan Sektörü'nde tanklar zincirleme patlar. Kancayı önce kenarlara at.":"Lesson note: In the Pirate Sector, tanks blow up in chains. Throw the claw at the edges first.",
"Ders notu: Büyük tank olmadan uzak bölgeye çıkma; dönüş yakıtı da hesapta.":"Lesson note: Don't head to a far zone without a big tank; count the fuel to get back, too.",
"Kilitli ilanlar: {0}. Akademi'de lisans alınca bu panoya düşer.":"Locked listings: {0}. They'll show up on this board once you get a license at the Academy.",
"İnişte gemiyi devirmemek için ne yapmalısın?":"What should you do to avoid tipping the ship over on landing?",
"Pistin üstünde yavaşlayıp düz inmek":"Slow down above the pad and land level",
"Motoru kapatıp süzülmek":"Cut the engine and glide",
"Yan yatarak inmek":"Land on your side",
"Teslimat ilanındaki \"rüzgârlı\" etiketi ne demek?":"What does the \"windy\" tag on a delivery listing mean?",
"Gemiyi yana iten akıntılar olacak":"There'll be currents pushing the ship sideways",
"Ödeme hızlı gelecek":"Payment will come fast",
"Yakıt bedava":"Fuel is free",
"Teslimata çıkmadan önce neye bakmalısın?":"What should you check before heading out on a delivery?",
"Yakıtın ilandaki miktara yetip yetmediğine":"Whether your fuel covers the amount in the listing",
"Ambarın boyasına":"The paint on the hold",
"Kantinin menüsüne":"The cantina menu",
"Pilotluk becerisi teslimatta ne sağlar?":"What does the Piloting skill give you on deliveries?",
"Daha geniş iniş toleransı ve ek yakıt":"Wider landing tolerance and extra fuel",
"Daha çok yolcu":"More passengers",
"Krell indirimi":"A Krell discount",
"Devre bulmacasında amaç nedir?":"What's the goal of the circuit puzzle?",
"Enerjiyi kaynaktan çıkışa kesintisiz ulaştırmak":"Get the energy from source to output without a break",
"Bütün kabloları kesmek":"Cut all the cables",
"Parçaları söküp satmak":"Strip the parts and sell them",
"Mühendislik becerisi tamirde ne kazandırır?":"What does the Engineering skill give you in repairs?",
"Ek süre ve ipucu":"Extra time and hints",
"Daha büyük devre":"A bigger circuit",
"Bedava yakıt":"Free fuel",
"\"İpucusuz\" etiketli işte ne olur?":"What happens on a job tagged \"No hints\"?",
"Yardım ışıkları yanmaz":"The help lights stay off",
"Ödeme yapılmaz":"You don't get paid",
"Devre küçülür":"The circuit shrinks",
"Tamirde kimler yardım edebilir?":"Who can help with repairs?",
"Ela ve Tolga":"Ela and Tolga",
"Sipariş teslim etmek için ne gerekir?":"What do you need to deliver an order?",
"Kargonda istenen eşyadan yeterince olması":"Enough of the requested item in your cargo",
"Akademi diploması":"An Academy diploma",
"Kumarhane kartı":"A casino card",
"Siparişler neden cazip?":"Why are orders worth it?",
"Pazardan çok daha iyi fiyat öder":"They pay far better than the market",
"Enerji kazandırır":"They give you energy",
"Borcu siler":"They wipe your debt",
"Pazarda aynı türden çok satarsan ne olur?":"What happens if you sell too much of one kind at the market?",
"Fiyat düşer":"The price drops",
"Fiyat artar":"The price goes up",
"Hiçbir şey olmaz":"Nothing happens",
