"Hiç harcamaz":"None at all",
"30 enerji":"30 energy",
"Bütün enerjini":"All your energy",
"Enerji kristalleri en çok nerede bulunur?":"Where are energy crystals found most?",
"Krell'in kasası":"Krell's safe",
"Patlayıcı tankı kancalarsan ne olur?":"What happens if you hook an explosive tank?",
"Çevresindekilerle birlikte patlar":"It blows up along with everything around it",
"Değeri ikiye katlanır":"Its value doubles",
"Yakıtın dolar":"Your fuel refills",
"Aynı bölgeye sık dalarsan ne olur?":"What happens if you dive the same zone too often?",
"Stok azalır, her gece biraz yenilenir":"Stock runs low and refills a bit each night",
"Bölge sonsuza dek kapanır":"The zone closes forever",
