"Kargo Pilotu (teslimat), Ayrıştırma, Devre Teknisyeni (tamir), Ticaret Ruhsatı (siparişler), Derin Tarama (kristal, uydu, kayıp eserler, Gaz Devi) ve Tehlikeli Bölge (Korsan Sektörü, Kayıp Yıldız).":"Cargo Pilot (delivery), Sorting, Circuit Technician (repair), Trade Permit (orders), Deep Scan (crystals, satellites, lost relics, Gas Giant) and Danger Zone (Pirate Sector, Lost Star).",
"Her lisans birkaç dersten oluşur. Günde bir ders alınır; son ders 3 soruluk bir sınavdır, 2'sini bilmen gerekir. Beceri eğitimleri de artık Akademi'de.":"Each license is a few lessons. One lesson a day; the last one is a 3-question exam and you need 2 right. Skill training is at the Academy now too.",
"14:00'te açılır. Yüksek mi alçak mı, Yıldız Çarkı, Kara Delik Zarı, Meteor Yarışı ve Nebula Slotu. Her el {0} dakika ve {1} enerji; günde en fazla {2} el.":"Opens at 14:00. High or Low, Star Wheel, Black Hole Dice, Meteor Race and Nebula Slots. Each hand is {0} minutes and {1} energy; max {2} hands a day.",
"Kasa uzun vadede kazanır. Kazanç moral verir, kayıp moral alır. 25 elde Gümüş üyelik daha yüksek bahis açar. Kumar kazancı Rex yarışına sayılmaz.":"The house wins in the long run. Wins boost morale, losses cost it. 25 hands unlocks Silver membership and higher stakes. Gambling winnings don't count toward the Rex race.",
"Sınamalar":"Trials",
"Her 4–10 günde bir (tehlike ayarına ve şansa bağlı) istasyonda bir sınama çıkar: korsan haracı, meteor yağmuru, virüs, salgın ya da denetim.":"Every 4–10 days (depending on the danger setting and luck) the station throws a trial at you: pirate shakedown, meteor shower, virus, outbreak or inspection.",
"Ya istenen parayı ödersin ya da kısa bir mini oyunla mücadele edersin. Kazanırsan hiçbir şey kaybetmezsin, küçük bir ödül alırsın; kaybedersen daha fazla para, bir dekor, kargo, sağlık ya da moral gider. Gün biterken karar vermediysen kaybetmiş sayılırsın.":"Either pay what they ask or fight it out in a short mini-game. Win and you lose nothing and get a small reward; lose and more money, a decor item, cargo, health or morale goes. If you haven't decided by the end of the day, it counts as a loss.",
"Klinikteki aşı salgına karşı korur; Tolga talebi pazarlıkla düşürmeyi deneyebilir.":"The clinic's vaccine protects against outbreaks; Tolga can try to haggle the demand down.",
