"Günün işi":"Job of the day",
"Her sabah teslimat, tamir ya da ayrıştırmadan biri seçilir; o türün ilanları gün boyu %25 fazla öder. İş kartında \"Günün işi\" etiketi görünür.":"Every morning one of delivery, repair or sorting is picked; listings of that type pay 25% more all day. The job card shows a \"Job of the day\" tag.",
