"Yeni Oyun+ {0}: Albümün, unvanların ve boyaların seninle. Borç {1}, başlangıç primi {2}, bütün işler %{3} daha fazla öder.":"New Game+ {0}: your album, titles and paint jobs come with you. Debt {1}, starter bonus {2}, all jobs pay {3}% more.",
