"{0}: Gün {1} başladı":"{0}: Day {1} has begun",
"Hurda kendini toplamıyor kaptan. Ben denedim.":"Scrap doesn't collect itself, captain. I tried.",
"Yeni ilanlar düştü. Hane seni bekliyor.":"New listings are up. The household's waiting for you.",
