"İlk 7 gece rıhtım ve gemi bakımı yarı fiyat. Yeni gemi daha büyük kazandırır ama masrafı da büyüktür.":"For the first 7 nights docking and ship upkeep are half price. A new ship earns more, but it costs more too.",
