"Tolga kapıda durdu, çantayı yere koydu. \"Bir hafta daha. Ama bir şey değişmezse gerçekten giderim.\" Bağ +12. Bu son şansın.":"Tolga stopped at the door and set his bag down. \"One more week. But if nothing changes, I'm really leaving.\" Bond +12. This is your last chance.",
"Tolga eşikte durdu. \"Bir hafta. Sonra yokum.\" Bağ +12. Bir daha sormayacak.":"Tolga stood on the threshold. \"One week. Then I'm gone.\" Bond +12. He won't ask again.",
