"En az bir yol arkadaşı seç.":"Pick at least one companion.",
"{0} · Gün {1}":"{0} · Day {1}",
"Devam et":"Continue",
"{0} · nakit {1} · borç {2}":"{0} · cash {1} · debt {2}",
"Adın":"Your name",
"+ haftalık {0}":"+ {0} weekly",
"· anlatıcı":"· narrator",
"Gecelik {6}{7}{8}":"Per night {6}{7}{8}",
"Birini, ikisini ya da üçünü seç. Daha çok arkadaş daha çok iş gücü ve yardım, ama daha çok masraf ve sorumluluk demek. İlk seçtiğin anlatıcı olur.":"Pick one, two or all three. More friends means more hands and more help, but also more costs and responsibility. Your first pick becomes the narrator.",
"{0} seçili · {1}/gece":"{0} selected · {1}/night",
"Anlatım":"Voice",
"Oyun sırasında Seyir Defteri'nden de değiştirebilirsin.":"You can also change this from the Logbook during play.",
"Yeni oyuna başla (kaydın silinir)":"Start a new game (deletes your save)",
"Hayata başla":"Begin life",
"Borçlu bir hurdacının istasyondaki hayatı. Kanca at, iş kovala, haneni doyur, gemini büyüt.":"Life of an indebted scrapper on a station. Cast the claw, chase jobs, feed your household, grow your ship.",
"Eylem hatası:":"Action error:",
"Bu işlem tamamlanamadı; oyun kaldığı yerden devam ediyor.":"That action couldn't finish; the game carries on where it left off.",
"Her zaman açık":"Always open",
"{0} şu an kapalı ({1}).":"{0} is closed right now ({1}).",
"Bu saatte yolculuk yapamazsın.":"You can't travel at this hour.",
"Yürüyecek enerjin bile yok. Bir şey ye ya da kestir.":"You don't even have the energy to walk. Eat something or take a nap.",
"Pıtırcık burnunu haritaya sürttü ve {0} üstünde mırladı. Bugün orada değerler %30 fazla, bir de kristal kokusu var.":"Pıtırcık rubbed its nose on the map and purred over {0}. Values there are 30% higher today, and there's a whiff of crystal.",
"Pıtırcık sensörlerini {0} yönüne çevirdi. Bugün orası bereketli.":"Pıtırcık turned its sensors toward {0}. Rich pickings there today.",
"Ela sana okulda öğrendiği bir şakayı anlattı. Şaka berbattı. Güldün. Moral +15, enerji +10.":"Ela told you a joke she learned at school. It was terrible. You laughed. Morale +15, energy +10.",
"Ela yanına oturdu, başını omzuna koydu. \"Başaracağız.\" Moral +15, enerji +10.":"Ela sat beside you and rested her head on your shoulder. \"We'll make it.\" Morale +15, energy +10.",
"Tolga telefonu açtı: \"Kanka, bir işin var mı? Hayır, bu sefer yasal.\" İş Merkezi'nde özel bir iş seni bekliyor.":"Tolga picks up the phone: \"Bro, got any work? No, it's legal this time.\" A special job is waiting for you at the Job Center.",
"Tolga eski bir tanıdığını aradı. İş Merkezi'nde ödemesi yüksek bir iş var.":"Tolga called an old acquaintance. There's a high-paying job at the Job Center.",
"Kırılacak":"Fragile",
"İniş hızı toleransı düşük.":"Low landing-speed tolerance.",
"Tolga'nın tanıdığı":"Tolga's contact",
"kısa":"short",
"Parça kurtarma":"Parts salvage",
"Kristal siparişi":"Crystal order",
"Enkaz temizliği":"Debris cleanup",
"Kara kutu kurtarma":"Black box recovery",
"Paran yetmiyor.":"You can't afford it.",
"Kimse hasta değil.":"Nobody's sick.",
"{0} ilacını aldı ve iyileşti.":"{0} took the medicine and got better.",
"Bandajı sardın. Sağlık +20.":"You wrapped the bandage. Health +20.",
"Bu hediyeyi verecek kimse yok.":"There's nobody to give this gift to.",
"{0} hediyeye bayıldı. Bağ +{1}.":"{0} loved the gift. Bond +{1}.",
"{0} hediyeyi sessizce aldı, gözleri parladı. Bağ +{1}.":"{0} quietly took the gift, eyes shining. Bond +{1}.",
"Haftalık yarışı kazandın: {0} / Rex {1}. Ödül {2}. {3}":"You won the weekly race: {0} / Rex {1}. Prize {2}. {3}",
"Haftalık yarışı Rex kazandı: {0} / sen {1}. {2}":"Rex won the weekly race: {0} / you {1}. {2}",
"Borçlu bir hurdacının uzay istasyonundaki hayatı. Kancayla hurda avla, iş kovala, haneni doyur, gemini büyüt.":"Life of an indebted scrapper on a space station. Hunt scrap with your claw, chase jobs, feed your household, grow your ship.",
"Koloni battığında elinde sadece bu gemi kaldı: \"Paslı Pelikan\". Galaksinin en külüstür hurda gemisi. Parasını da tefeci Krell'den borç aldın. Krell gülümsüyor. Krell hep gülümsüyor.":"When the colony went under, this ship was all you had left: the \"Rusty Pelican\". The most beat-up scrap bucket in the galaxy. And you bought it with money borrowed from Krell the loan shark. Krell smiles. Krell always smiles.",
"Plan basit: hurda topla, sat, borcu öde. Sonra bu tenekeyi satıp gerçek bir gemi al.":"The plan is simple: collect scrap, sell it, pay off the debt. Then sell this tin can and buy a real ship.",
"Koloni battığında elinde sadece bu gemi kaldı: \"Paslı Pelikan\". Onu da Krell'den aldığın borçla aldın. Oksijen her gün, kira her ay. İstasyon kimseye ikinci şans vermez.":"When the colony went under, this ship was all you had left: the \"Rusty Pelican\". Bought, of course, with a loan from Krell. Oxygen every day, rent every month. The station gives nobody a second chance.",
"Borcu kapat. Gemiyi sat. Daha iyisini al. Hayatta kal.":"Clear the debt. Sell the ship. Buy a better one. Stay alive.",
"SON ÖDEME! Krell ağlıyor, sen dans ediyorsun, Gus bedava güveç dağıtıyor. Paslı Pelikan artık tamamen senin.":"FINAL PAYMENT! Krell is crying, you are dancing, Gus is handing out free stew. The Rusty Pelican is all yours now.",
"Tersanede bir gemi gözüne çarptı: Gezgin Martı. Pelikan'ı satıp onu almanın vakti geldi mi?":"A ship caught your eye at the shipyard: the Wandering Gull. Is it time to sell the Pelican and buy her?",
"Son ödemeyi yaptığında Krell sadece başını salladı. \"Bir dahaki sefere.\" Bir dahaki sefer olmayacak.":"When you made the final payment, Krell just nodded. \"Until next time.\" There won't be a next time.",
"Tersanede Gezgin Martı duruyor. Pelikan'ı satarsan ona yaklaşırsın. Belki banka da yardım eder.":"The Wandering Gull is waiting at the shipyard. Sell the Pelican and you're one step closer. Maybe the bank will chip in too.",
"Demir Balina'nın ambarı o kadar büyük ki içinde kaybolabilirsin. Gus açılış için güveç yaptı, Rex kıskançlıktan mor oldu, Krell tebrik kartı gönderdi (içinde kredi teklifi var).":"The Iron Whale's hold is so big you could get lost in it. Gus made stew for the launch, Rex turned purple with envy, and Krell sent a congratulations card (with a loan offer inside).",
"Koloniden çıktığın o günden bu yana uzun yol geldin. Hikâye burada biter ama hayat devam ediyor. İstediğin kadar oynamaya devam edebilirsin.":"You've come a long way since the day you left the colony. The story ends here, but life goes on. Keep playing as long as you like.",
"Demir Balina rıhtımda bekliyor. Bir zamanlar kolonideki fabrikanın vinçlerine bakıp hayal ettiğin şey buydu.":"The Iron Whale is waiting at the dock. This is what you dreamed of, staring at the factory cranes back in the colony.",
"Borçsuz, güçlü, ayakta. Hikâye burada biter. Hayat ise sürüyor; istediğin kadar devam edebilirsin.":"Debt-free, strong, still standing. The story ends here. Life goes on, though; keep going as long as you like.",
"Tebrikler! Galaksinin en külüstür hurda gemisi \"Paslı Pelikan\" artık senin. Tek bir küçük sorun var: parasını tefeci Krell'den borç aldın. Krell gülümsüyor. Krell hep gülümsüyor.":"Congratulations! The most beat-up scrap bucket in the galaxy, the \"Rusty Pelican\", is now yours. Just one tiny problem: you borrowed the money from Krell the loan shark. Krell smiles. Krell always smiles.",
"Hurda topla, sat, borcunu öde. Belki bir gün yatağın bir dolap kadar geniş olur.":"Collect scrap, sell it, pay your debt. Maybe one day your bed will be as big as a wardrobe.",
"Ara: kahve, kristal, lisans, yakıt…":"Search: coffee, crystal, license, fuel…",
